// Generated by AI QA Agent from .qa/scenarios/checkout.json — regenerated when scenarios change.
import { test, expect, type Locator, type Page } from '@company/ai-qa/playwright';

type Item = 'Ceramic Mug' | 'Canvas Tote' | 'Dot Notebook';

const MINUS = '−';

const mainNav = (page: Page) => page.getByRole('navigation', { name: 'Main' });
const cartLink = (page: Page) => mainNav(page).getByRole('link', { name: /^Checkout/ });
/** The cart badge (span with aria-label "N items in cart"); matched by label so it works while the nav is collapsed. */
const cartBadge = (page: Page) => page.getByLabel(/^\d+ items? in cart$/);
const menuButton = (page: Page) => page.getByRole('button', { name: /^(Open|Close) menu$/ });

const orderList = (page: Page) => page.getByRole('list', { name: 'Order items' });
const orderLines = (page: Page) => orderList(page).getByRole('listitem');
const couponInput = (page: Page) => page.getByRole('textbox', { name: 'Coupon code', exact: true });
const applyButton = (page: Page) => page.getByRole('button', { name: 'Apply', exact: true });
const applyingButton = (page: Page) => page.getByRole('button', { name: 'Applying…', exact: true });
const placeOrderButton = (page: Page) => page.getByRole('button', { name: 'Place order', exact: true });
const removeButton = (page: Page, item: Item) => page.getByRole('button', { name: `Remove ${item}`, exact: true });
const statusMessage = (page: Page) => page.getByRole('status');
const alertMessage = (page: Page) => page.getByRole('alert');
const subtotal = (page: Page) => page.getByTestId('subtotal');
const discount = (page: Page) => page.getByTestId('discount');
const total = (page: Page) => page.getByTestId('total');
const checkoutHeading = (page: Page) => page.getByRole('heading', { level: 1, name: 'Checkout', exact: true });
const emptyHeading = (page: Page) => page.getByRole('heading', { level: 1, name: 'Your cart is empty', exact: true });
const browseLink = (page: Page) => page.getByRole('link', { name: 'Browse products', exact: true });

function addButton(page: Page, product: Item) {
  return page.getByRole('button', { name: `Add ${product} to cart`, exact: true });
}

async function addToCart(page: Page, product: Item, times = 1) {
  for (let i = 0; i < times; i++) {
    await addButton(page, product).click();
  }
}

/** Make sure the header nav is usable (opens the mobile menu when the links are collapsed). */
async function ensureNavVisible(page: Page) {
  if (!(await cartLink(page).isVisible())) {
    await menuButton(page).click();
  }
  await expect(cartLink(page)).toBeVisible();
}

/** Marks the current document so a later check can prove no full page load happened. */
async function markDocument(page: Page) {
  await page.evaluate(() => {
    (window as unknown as Record<string, unknown>).__qaNoReload = true;
  });
}

async function expectDocumentNotReloaded(page: Page) {
  const marker = await page.evaluate(() => (window as unknown as Record<string, unknown>).__qaNoReload);
  expect(marker, 'page must not have been reloaded').toBe(true);
}

/** Open / (fresh session), add the given products through the UI and reach /checkout via the header link. */
async function openCheckoutWithItems(page: Page, items: ReadonlyArray<readonly [Item, number]>) {
  await page.goto('/');
  await markDocument(page);
  let count = 0;
  for (const [name, qty] of items) {
    await addToCart(page, name, qty);
    count += qty;
    await expect(cartBadge(page)).toHaveText(String(count));
  }
  await ensureNavVisible(page);
  await cartLink(page).click();
  await expect(page).toHaveURL(/\/checkout$/);
  await expect(checkoutHeading(page)).toBeVisible();
  await expectDocumentNotReloaded(page);
}

async function applyCoupon(page: Page, code: string) {
  await couponInput(page).fill(code);
  await applyButton(page).click();
}

async function box(locator: Locator) {
  const b = await locator.boundingBox();
  expect(b, 'element should have a bounding box').not.toBeNull();
  return b!;
}

function expectClose(actual: number, expected: number, tolerance: number, label: string) {
  expect(Math.abs(actual - expected), `${label}: expected ~${expected}, got ${actual}`).toBeLessThanOrEqual(tolerance);
}

test('CHECKOUT-001: Checkout lists cart lines with correct line prices, subtotal and total', {
  tag: ['@functional', '@cart', '@desktop', '@high'],
}, async ({ page }) => {
  await test.step('Open /', async () => {
    await page.goto('/');
    await markDocument(page);
    await expect(cartBadge(page)).toHaveText('0');
  });

  await test.step("Click 'Add Ceramic Mug to cart' twice and 'Add Canvas Tote to cart' once", async () => {
    await addToCart(page, 'Ceramic Mug', 2);
    await expect(cartBadge(page)).toHaveText('2');
    await addToCart(page, 'Canvas Tote', 1);
    await expect(cartBadge(page)).toHaveText('3');
  });

  await test.step("Click the header nav link 'Checkout' (client-side navigation)", async () => {
    await cartLink(page).click();
    await expect(page).toHaveURL(/\/checkout$/);
    await expectDocumentNotReloaded(page);
  });

  await test.step("Read the 'Order items' list and the summary", async () => {
    await expect(checkoutHeading(page)).toBeVisible();

    const lines = orderLines(page);
    await expect(lines).toHaveCount(2);

    const mug = lines.filter({ hasText: 'Ceramic Mug' });
    await expect(mug).toHaveCount(1);
    await expect(mug).toContainText('Ceramic Mug × 2');
    await expect(mug).toContainText('$36.00');
    await expect(mug.getByRole('button', { name: 'Remove Ceramic Mug', exact: true })).toHaveText('Remove');

    const tote = lines.filter({ hasText: 'Canvas Tote' });
    await expect(tote).toHaveCount(1);
    await expect(tote).toContainText('Canvas Tote × 1');
    await expect(tote).toContainText('$24.00');
    await expect(tote.getByRole('button', { name: 'Remove Canvas Tote', exact: true })).toHaveText('Remove');

    await expect(subtotal(page)).toHaveText('$60.00');
    await expect(total(page)).toHaveText('$60.00');
    await expect(discount(page)).toHaveCount(0);
    await expect(page.getByText('Discount', { exact: true })).toHaveCount(0);
  });
});

