test("CHECKOUT-008: 'Place order' gives user feedback and completes the order", {
  tag: ['@functional', '@checkout', '@desktop', '@medium'],
}, async ({ page }) => {
  let urlBefore = '';

  await test.step("Add 'Ceramic Mug' on /, then go to /checkout via the 'Checkout' nav link", async () => {
    await openCheckoutWithItems(page, [['Ceramic Mug', 1]]);
    urlBefore = page.url();
    await expect(placeOrderButton(page)).toBeVisible();
    await expect(placeOrderButton(page)).toBeEnabled();
  });

  await test.step("Click the full-width 'Place order' button", async () => {
    await placeOrderButton(page).click();
  });

  await test.step('Observe the page and URL: the click must produce visible feedback', async () => {
    // Any of: navigation to a confirmation view, an order confirmation message,
    // the cart being cleared, or the button entering a processing/disabled state.
    const feedback = async () => {
      if (page.url() !== urlBefore) return true;
      if ((await checkoutHeading(page).count()) === 0) return true;
      if ((await page.getByText(/order (has been )?(placed|confirmed|received)|thank you|confirmation/i).count()) > 0) return true;
      if ((await orderLines(page).count()) === 0) return true;
      const button = page.getByRole('button', { name: /^Place order$/ });
      if ((await button.count()) === 0) return true;
      if (await button.isDisabled()) return true;
      return false;
    };
    await expect
      .poll(feedback, {
        message: "'Place order' must confirm the order, navigate, clear the cart or show a processing state (silence is a defect)",
        timeout: 5_000,
      })
      .toBe(true);
  });
});

