test('CHECKOUT-010: Checkout fits a 390px mobile viewport without horizontal overflow', {
  tag: ['@responsive', '@checkout', '@mobile', '@medium'],
}, async ({ page, qa }) => {
  const viewportWidth = page.viewportSize()?.width ?? 390;

  /** Asserts that an element lies fully inside the viewport horizontally. */
  async function expectInsideViewport(locator: Locator, label: string) {
    const b = await box(locator);
    expect(b.x, `${label} left edge`).toBeGreaterThanOrEqual(-0.5);
    expect(b.x + b.width, `${label} right edge`).toBeLessThanOrEqual(viewportWidth + 0.5);
    return b;
  }

  async function expectNotClipped(locator: Locator, label: string) {
    const clipped = await locator.evaluate((el) => el.scrollWidth > el.clientWidth + 1);
    expect(clipped, `${label} must not be clipped`).toBe(false);
  }

  async function checkLayout(stage: string) {
    await qa.expectNoHorizontalOverflow();
    const scrollWidth = await page.evaluate(() => document.documentElement.scrollWidth);
    expect(scrollWidth, `${stage}: document scrollWidth`).toBeLessThanOrEqual(viewportWidth);

    // Order lines: name, price and Remove side by side without overlap or clipping.
    const lines = orderLines(page);
    const lineCount = await lines.count();
    expect(lineCount, `${stage}: number of order lines`).toBe(2);
    const expectedLines = [
      { name: 'Ceramic Mug × 2', price: '$36.00', remove: 'Remove Ceramic Mug' },
      { name: 'Canvas Tote × 1', price: '$24.00', remove: 'Remove Canvas Tote' },
    ];
    for (const [i, expected] of expectedLines.entries()) {
      const line = lines.nth(i);
      const lineBox = await expectInsideViewport(line, `${stage}: line ${i + 1}`);
      await expectNotClipped(line, `${stage}: line ${i + 1}`);
      const nameBox = await expectInsideViewport(line.getByText(expected.name, { exact: true }), `${stage}: line ${i + 1} name`);
      const priceBox = await expectInsideViewport(line.getByText(expected.price, { exact: true }), `${stage}: line ${i + 1} price`);
      const removeBox = await expectInsideViewport(
        line.getByRole('button', { name: expected.remove, exact: true }),
        `${stage}: line ${i + 1} Remove`,
      );
      expect(nameBox.x + nameBox.width, `${stage}: line ${i + 1} name must not overlap price`).toBeLessThanOrEqual(priceBox.x + 0.5);
      expect(priceBox.x + priceBox.width, `${stage}: line ${i + 1} price must not overlap Remove`).toBeLessThanOrEqual(removeBox.x + 0.5);
      expect(removeBox.x + removeBox.width, `${stage}: line ${i + 1} Remove inside its row`).toBeLessThanOrEqual(lineBox.x + lineBox.width + 0.5);
    }

    // Coupon row: 44px controls inside the viewport.
    const inputBox = await expectInsideViewport(couponInput(page), `${stage}: coupon textbox`);
    const applyBox = await expectInsideViewport(applyButton(page), `${stage}: Apply button`);
    expectClose(inputBox.height, 44, 0.5, `${stage}: coupon textbox height`);
    expectClose(applyBox.height, 44, 0.5, `${stage}: Apply button height`);
    expect(inputBox.x + inputBox.width, `${stage}: coupon textbox must not overlap Apply`).toBeLessThanOrEqual(applyBox.x + 0.5);
    expect(inputBox.width, `${stage}: coupon textbox stays usable`).toBeGreaterThan(100);

    // Summary rows: labels and right-aligned values readable and unclipped.
    const rows: Array<{ label: string; value: Locator }> = [
      { label: 'Subtotal', value: subtotal(page) },
      { label: 'Total', value: total(page) },
    ];
    if (stage === 'after coupon') rows.splice(1, 0, { label: 'Discount', value: discount(page) });
    for (const row of rows) {
      const labelLocator = page.getByText(row.label, { exact: true });
      await expect(labelLocator, `${stage}: ${row.label} label`).toBeVisible();
      await expect(row.value, `${stage}: ${row.label} value`).toBeVisible();
      const labelBox = await expectInsideViewport(labelLocator, `${stage}: ${row.label} label`);
      const valueBox = await expectInsideViewport(row.value, `${stage}: ${row.label} value`);
      await expectNotClipped(labelLocator, `${stage}: ${row.label} label`);
      await expectNotClipped(row.value, `${stage}: ${row.label} value`);
      expect(labelBox.x + labelBox.width, `${stage}: ${row.label} label must not overlap its value`).toBeLessThanOrEqual(valueBox.x + 0.5);
      expect(valueBox.x, `${stage}: ${row.label} value is right of its label`).toBeGreaterThan(labelBox.x);
    }

    // Place order spans the content width with a 44px tap height.
    const orderBox = await expectInsideViewport(placeOrderButton(page), `${stage}: Place order`);
    expectClose(orderBox.height, 44, 0.5, `${stage}: Place order height`);
    expectClose(orderBox.width, viewportWidth - 48, 2, `${stage}: Place order width (content width)`);

    // 24px side gutters where the layout allows.
    const listBox = await box(orderList(page));
    expectClose(listBox.x, 24, 1, `${stage}: order list left gutter`);
    expectClose(orderBox.x, 24, 1, `${stage}: Place order left gutter`);
    expectClose(viewportWidth - (orderBox.x + orderBox.width), 24, 1, `${stage}: Place order right gutter`);
  }

  await test.step("Open /checkout as described: add 'Ceramic Mug' twice and 'Canvas Tote' once, use the 'Checkout' link", async () => {
    await openCheckoutWithItems(page, [
      ['Ceramic Mug', 2],
      ['Canvas Tote', 1],
    ]);
  });

  await test.step('Check the page for horizontal scrolling, order lines, coupon row, summary rows and Place order', async () => {
    await checkLayout('before coupon');
  });

  await test.step("Apply 'SAVE10' and check the layout again", async () => {
    await applyCoupon(page, 'SAVE10');
    await expect(statusMessage(page)).toHaveText('Coupon SAVE10 applied: 10% off');
    await expect(discount(page)).toHaveText(`${MINUS}$6.00`);
    await checkLayout('after coupon');
  });
});
